<?php get_header(); $is_magazine=is_home() || is_category() || is_tag() || (is_archive() && get_post_type()==='post');$layout=$is_magazine?get_theme_mod('md_archive_sidebar','right'):'none'; ?><main id="main" class="container md-magazine-layout <?php echo esc_attr($layout==='none'?'without-sidebar':'sidebar-'.$layout); ?>"><div class="md-magazine-main"><h1><?php echo is_home()?'مجله مروارید درون':esc_html(get_the_archive_title()); ?></h1><div class="md-archive-cards card-grid"><?php if(have_posts()):while(have_posts()):the_post();md_card(get_the_ID());endwhile;else: ?><p>هنوز محتوایی منتشر نشده است.</p><?php endif; ?></div><div class="pagination"><?php the_posts_pagination(); ?></div></div><?php if($is_magazine)md_render_sidebar('magazine', $layout); ?></main><?php get_footer(); ?>